-- Fixed 279-row executable manifest. Generated from the reviewed TSV; no runtime target discovery.
CREATE TEMPORARY TABLE school_planned_canonicalization_manifest (
  lesson_id uuid PRIMARY KEY,
  student_id uuid NOT NULL,
  lesson_date date NOT NULL,
  status text NOT NULL,
  generation_batch_id text,
  current_business_entity_id uuid NOT NULL,
  target_business_entity_id uuid NOT NULL,
  before_updated_at timestamptz NOT NULL,
  before_row_hash text NOT NULL,
  before_stable_row_hash text NOT NULL,
  expected_after_stable_row_hash text NOT NULL,
  target_billing_month text NOT NULL,
  target_billing_week_start_date date NOT NULL,
  target_student_settlement_month text NOT NULL,
  target_billing_month_source text NOT NULL,
  target_billing_month_decided_at timestamptz NOT NULL,
  evidence_source text NOT NULL,
  evidence_version text NOT NULL,
  evidence_recorded_at timestamptz NOT NULL,
  legacy_evidence_month text NOT NULL,
  has_bill_relation boolean NOT NULL,
  locked_student_settlement_legacy_scope boolean NOT NULL,
  locked_student_settlement_target_scope boolean NOT NULL,
  has_locked_wage boolean NOT NULL,
  linked_actual_count integer NOT NULL
) ON COMMIT DROP;

